// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {EtherCartel} from "../src/EtherCartel.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    EtherCartel c;

    function setUp() public {
        c = new EtherCartel();
    }

    function _runTest(uint256 drugs) internal {
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(c.marketDrugs() == 0);
        try c.seedMarket{value: 0}(drugs) {} catch { return; }
        assertTrue(c.initialized() == true);
    }

    function testFuzz_runTest(uint256 drugs) public {
        _runTest(drugs);
    }

    receive() external payable {}
}
